function text(value) {
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) return value.map(text).join(' ');
  if (value && typeof value === 'object') return value.text ?? value.content ?? '';
  return '';
}

const source = $('Pull 1 sales row').first().json;
const raw =
  $json.message?.content ??
  $json.text ??
  $json.output ??
  $json.content ??
  '';
const draft = text(raw).trim();
return [{ json: { ...source, draft } }];

const draft = String($json.draft || '').trim();
const sentences = (draft.match(/[.!?](?=\s|$)/g) || []).length;
const lengthOk = draft.length >= 80 && draft.length <= 500;
const sentenceOk = sentences === 2;
const urlOk = !/https?:\/\//i.test(draft);
const placeholderOk = !/\[[^\]]+\]|\{\{[^}]+\}\}/.test(draft);
const pass = lengthOk && sentenceOk && urlOk && placeholderOk;

const reasons = [];
if (!lengthOk) reasons.push('length outside 80-500');
if (!sentenceOk) reasons.push('not exactly 2 sentences');
if (!urlOk) reasons.push('contains URL');
if (!placeholderOk) reasons.push('contains placeholder');

return [{
  json: {
    ...$json,
    guardrail_pass: pass,
    guardrail_reason: pass ? 'ok' : reasons.join('; '),
    guardrail_checks: {
      length_ok: lengthOk,
      sentence_ok: sentenceOk,
      url_ok: urlOk,
      placeholder_ok: placeholderOk
    }
  }
}];

